from typing import List

class Solution:
    def findPairs(self, nums: List[int], k: int) -> int:
        if k < 0:
            return 0
        count = 0
        seen = set()
        appeared = set()
        for num in nums:
            if num - k in seen and num - k not in appeared:
                count += 1
                appeared.add(num - k)
            if k == 0:
                if num in seen and num not in appeared:
                    count += 1
                    appeared.add(num)
            seen.add(num)
        return count
